# nginx (DMZ 10.20.0.10) : site public + reverse proxy vers l'API (10.20.0.70:5000)
worker_processes 1;
events { worker_connections 512; }

http {
    include       /etc/nginx/mime.types;
    default_type  application/octet-stream;
    server_tokens off;

    log_format p6 '$time_iso8601 $remote_addr "$request" $status $body_bytes_sent '
                  '$request_time "$http_user_agent"';
    access_log /var/log/nginx/access.log p6;

    upstream api { server 10.20.0.70:5000; }

    # FA1 : HTTP (80)
    server {
        listen 80 default_server;
        server_name _;
        root /usr/share/nginx/html;
        location /api/ {
            proxy_pass http://api;
            proxy_set_header Host $host;
            proxy_set_header X-Real-IP $remote_addr;
            proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
            proxy_connect_timeout 2s;
            proxy_read_timeout 10s;
        }
        location / { try_files $uri $uri/ =404; }
    }

    # FA1 : HTTPS (443), certificat auto-signe genere par setup.sh
    server {
        listen 443 ssl default_server;
        server_name _;
        ssl_certificate     /etc/nginx/certs/p6.crt;
        ssl_certificate_key /etc/nginx/certs/p6.key;
        ssl_protocols TLSv1.2 TLSv1.3;
        root /usr/share/nginx/html;
        location /api/ {
            proxy_pass http://api;
            proxy_set_header Host $host;
            proxy_set_header X-Real-IP $remote_addr;
            proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
            proxy_connect_timeout 2s;
            proxy_read_timeout 10s;
        }
        location / { try_files $uri $uri/ =404; }
    }
}

