// bind9 (DMZ 10.20.0.40) : zone publique p6.lab, serveur faisant autorite.
// Pas de recursion : le laboratoire n'a pas d'acces a Internet, et on evite un resolveur ouvert.
options {
    directory "/var/cache/bind";
    listen-on { any; };
    listen-on-v6 { none; };
    recursion no;
    allow-query { any; };
    allow-transfer { none; };
    version "non communiquee";
};

logging {
    channel requetes { stderr; severity info; print-time yes; };
    category queries { requetes; };
    category default { requetes; };
};

zone "p6.lab" {
    type primary;
    file "/etc/bind/db.p6.lab";
};

